'use strict';
let areasPromise=null;
async function ensureAreas(){
  if(window.areasReady)return;
  if(areasPromise)return areasPromise;
  areasPromise=(async()=>{try{
    $('status').textContent='Carregando as áreas das oito rodadas…';
    window.explorerLoading?.('Aguardando os resumos e carregando as áreas. Em conexão lenta, esta etapa pode levar mais tempo.');
    await Promise.all([window.metadataReady,window.overviewReady]);
    if(!data||!overviewData)throw Error('A base de resumo não carregou. Use Verificar nova versão.');
    const revision=overviewData.areas_revision;
    const rows=await fastJSON('areas.json?v='+revision);if(rows.length!==overviewData.total_included)throw Error('Versões incompatíveis. Verifique a atualização.');
    data.rows=rows;overviewData.rows=rows;window.areasRevision=revision;window.areasReady=true;
    const uf=$('state').value;$('state').innerHTML='<option value="">Todos os estados</option>'+[...new Set(rows.map(r=>r.u))].sort().map(s=>`<option>${esc(s)}</option>`).join('');$('state').value=uf;
    render();refreshInsights();$('status').textContent='';window.explorerLoaded?.();
  }catch(e){$('status').textContent=e.message;window.explorerFailed?.(e.message);throw e}finally{areasPromise=null}})();return areasPromise;
}
const oldView=view;view=function(name){oldView(name);activateSection(name)};
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>activateSection(b.dataset.view)));
async function activateSection(name){try{if(['explore','profiles','simulator'].includes(name))await ensureAreas();if(name==='explore'){mapBase();mapDots()}if(name==='profiles')renderMunicipalities();if(name==='participants')await showParticipants();if(name==='simulator')await initSimulator()}catch(e){$('status').textContent=e.message}}

const glossary={
 'Áreas incluídas nas rodadas':'Quantidade de registros de área por rodada. Inclui a rodada social, o edital cancelado e situações excluídas do modelo. Um processo pode aparecer em mais de uma rodada; não é uma contagem de terrenos únicos.',
 'Incluídas nas oito rodadas':'Registros de área por rodada na base atual, inclusive rodadas social e cancelada. O mesmo processo pode reaparecer.',
 'Resultados comerciais válidos':'Resultados Arrematada, Conquistada ou Livre das rodadas 1 a 5 e 8. Este recorte exclui a rodada social, o edital cancelado, retiradas e suspensões. É o conjunto elegível do experimento.',
 'Arrematada':'Área com resultado de leilão e lance vencedor positivo. O lance disputa a prioridade para requerer o título minerário. Não comprova pagamento nem autorização para iniciar a mineração.',
 'Áreas arrematadas':'Áreas com lance vencedor registrado. A soma é por rodada; não significa títulos concedidos ou pagamentos recebidos.',
 'Conquistada':'Área destinada na oferta pública sem disputa de lances, quando há um único interessado. Pode haver emolumentos. Não significa que a jazida vale zero nem que o título foi concedido.',
 'Livre':'Situação registrada ao final daquela rodada. Pode decorrer de ausência de interesse ou outras ocorrências previstas no edital. Não identifica a causa individual e não comprova disponibilidade hoje; consulte os eventos.',
 'Lances vencedores registrados':'Soma nominal dos valores vencedores ligados às áreas arrematadas. Não inclui todos os lances apresentados, nem comprova arrecadação recebida.',
 'Lances vencedores acumulados':'Soma dos lances vencedores registrados até cada rodada, sem correção pela inflação. As rodadas 6 e 7 não acrescentam lance financeiro comparável.',
 'Processos distintos':'Contagem de números de processo diferentes. Um processo pode aparecer em várias rodadas; poligonais atuais podem diferir das antigas.',
 'Comerciais válidas':'Áreas elegíveis do recorte comercial: Arrematada, Conquistada e Livre, apenas nas rodadas comerciais.',
 'Incluídas na base':'Áreas por rodada presentes no arquivo de resultados. Inclui situações administrativas que não são leilão concluído.',
 'Lance mediano positivo':'Metade dos lances positivos está abaixo e metade acima deste valor. Não inclui áreas sem lance nem estima o valor econômico do depósito.',
 'Município / UF':'Localização vinculada à área ou ao processo. Uma área pode estar associada a mais de um município. Não é necessariamente o domicílio do participante.'
};
const help=document.createElement('div');help.id='metric-help';help.className='help-popup';help.role='tooltip';help.hidden=true;document.body.append(help);let helpOwner;
let helpCloseTimer;function closeHelp(){clearTimeout(helpCloseTimer);help.hidden=true;if(helpOwner)helpOwner.removeAttribute('aria-describedby');helpOwner=null}
function showHelp(el){if(!el?.dataset.help)return;closeHelp();helpOwner=el;help.textContent=el.dataset.help;help.hidden=false;el.setAttribute('aria-describedby','metric-help');const r=el.getBoundingClientRect();help.style.left=Math.max(12,Math.min(r.left,innerWidth-help.offsetWidth-12))+'px';help.style.top=Math.max(12,Math.min(r.bottom+8,innerHeight-help.offsetHeight-12))+'px'}
function addHints(){document.querySelectorAll('#overview span,#overview th,#overview button,#explore label,#explore .badge,#explore [data-result],#profiles th').forEach(el=>{if(el.dataset.help)return;const text=[...el.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();const value=glossary[text];if(!value)return;el.dataset.help=value;el.classList.add('help-term');if(!el.matches('button,a,input,select'))el.tabIndex=0;el.title='Explicação: '+text})}
document.addEventListener('pointerover',e=>{clearTimeout(helpCloseTimer);showHelp(e.target.closest('[data-help]'))});document.addEventListener('focusin',e=>showHelp(e.target.closest('[data-help]')));document.addEventListener('pointerout',e=>{if(e.target.closest('[data-help]')||e.target===help)helpCloseTimer=setTimeout(closeHelp,200)});document.addEventListener('focusout',closeHelp);document.addEventListener('click',e=>{const t=e.target.closest('[data-help]');if(t)showHelp(t);else if(e.target!==help)closeHelp()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeHelp()});window.addEventListener('scroll',closeHelp,{passive:true});
let hintQueued=false;new MutationObserver(()=>{if(hintQueued)return;hintQueued=true;requestAnimationFrame(()=>{hintQueued=false;addHints()})}).observe(document.querySelector('main'),{childList:true,subtree:true});addHints();
$('funnel').before(Object.assign(document.createElement('p'),{className:'hint-intro',textContent:'Passe o cursor ou use Tab nos termos sublinhados para entender cada indicador.'}));

const hypotheses=[
 ['Floresta aleatória · histórico','Combinar árvores reduz a instabilidade de regras individuais. Eventos e títulos anteriores podem conter informação além de tamanho e localização.','Árvores treinadas com reamostragem e subconjuntos de variáveis; médias das previsões.','Captura interações. Pode memorizar padrões administrativos e erra na extrapolação de lances extremos. Regressor selecionado.'],
 ['Extra Trees · histórico','Aumentar a aleatoriedade dos cortes pode reduzir sobreajuste do histórico.','Mais aleatoriedade na construção das árvores; mesmos grupos de variáveis históricas.','Permite comparar a estratégia de árvores mantendo o conjunto de variáveis. Não foi selecionado.'],
 ['Boosting · básico','Quatro características da oferta já permitem distinguir parte da procura.','Árvores sucessivas corrigem erros anteriores; UF, regime, log da área e ano do processo.','Mais simples em informação; classificador selecionado pelo Brier da 5ª rodada.'],
 ['Boosting · histórico','Adicionar registros administrativos anteriores melhora o modelo básico.','Mesmo algoritmo, com eventos, títulos, substâncias históricas e contagens de titulares.','Testa o ganho da informação histórica dentro do mesmo algoritmo. Mais variáveis não garantem melhor resultado.'],
 ['Logística + Ridge · histórico','Uma relação aditiva regularizada pode ser suficiente e mais estável.','Regressão logística para arrematação e Ridge para log do lance; padronização numérica.','Referência aprendida mais simples; não representa interações não lineares automaticamente.'],
 ['Boosting · território','O contexto econômico municipal acrescenta sinal ao histórico.','Acrescenta CFEM, DIPEM, associações e indicadores de dados ausentes.','Vínculos municipais atuais e DIPEM aberta após a 8ª: diagnóstico retrospectivo, sem comprovação de uso à época.']
];
const methodology=document.createElement('section');methodology.className='panel';methodology.innerHTML=`<h2>Seis candidatos, duas tarefas e uma referência</h2><p>O aprendizado é <b>supervisionado</b>: usamos resultados conhecidos para aprender a distinguir áreas arrematadas e estimar o lance vencedor quando existe arrematação. Não houve agrupamento não supervisionado. Cada uma das seis configurações tem um classificador e um regressor.</p><p>A tabela com três linhas resume a <b>referência constante</b>, o <b>experimento inicial</b> e a <b>seleção V2</b>. Ela não representa o total de candidatos testados. A referência constante usa a proporção de arrematação e a mediana dos lances do treino.</p><div class="table-scroll"><table class="decision-table"><thead><tr><th>Configuração</th><th>Hipótese preditiva</th><th>Como funciona / informação usada</th><th>Diferença e limite</th></tr></thead><tbody>${hypotheses.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p class="notice">São hipóteses de capacidade preditiva, não testes causais ou hipóteses estatísticas confirmadas por significância. As métricas de cada candidato estão na tabela de seleção abaixo.</p><details class="decision-disclosure"><summary>Por que estes modelos? Por que não testar mais?</summary><p>O experimento compara uma referência simples, modelos lineares e diferentes estratégias de árvores, além do efeito de acrescentar dados históricos e territoriais. Foram escolhas de escopo; não foi uma busca exaustiva nem uma demonstração de que outros algoritmos seriam piores. Não foram testadas redes neurais, CatBoost ou XGBoost nesta versão.</p><p>Existem muitas áreas, mas só seis rodadas comerciais elegíveis. Aumentar a lista de algoritmos e escolher o melhor depois de observar a 8ª pode favorecer o acaso. A próxima comparação deve fixar previamente as métricas, usar validação temporal em várias rodadas e reservar uma nova rodada para teste prospectivo. Também são necessários calibração, avaliação por UF/regime e importância por permutação estável entre rodadas.</p></details><details class="decision-disclosure"><summary>Hipóteses e restrições dos experimentos adicionais</summary><p><b>Faixas de quantis:</b> modelos de boosting estimam os percentis 10 e 90 com variáveis territoriais. A hipótese é delimitar a dispersão; a faixa nominal de 80% cobriu apenas 62,3% dos lances positivos. Não está calibrada e não usa somente informações comprovadamente públicas à época.</p><p><b>Contexto de rodada:</b> tamanho e composição da oferta, concentração por estado e IPCA podem explicar mudanças entre rodadas. A composição foi reconstruída retrospectivamente; esse ensaio não substitui a seleção principal e não identifica causalmente o efeito de uma regra.</p><p><b>Transformação do lance:</b> a regressão aprende log1p(valor), depois aplica expm1. O centro nessa escala não é a média monetária esperada. Por isso, somar probabilidade × lance central não é uma previsão validada de receita.</p></details><p><a href="ciencia/FICHA_DO_MODELO.md" download>Ficha completa dos modelos</a> · <a href="ciencia/reproduzir.py" download>Reprodução em Python</a> · <a href="ciencia/lancemineral-ciencia-aberta.zip" download>Código, dados congelados e verificações</a></p>`;
$('models').children[0].after(methodology);
function section(id,html){const el=document.createElement('section');el.id=id;el.className='view';el.hidden=true;el.innerHTML=html;document.querySelector('main footer').before(el)}
section('participants',`<section class="panel"><h2>Quem participa e quem arremata?</h2><p>Perfil agregado dos cadastros de participação e dos vencedores registrados. Os grupos não são intercambiáveis: manifestar interesse não comprova apresentação de lance.</p><div class="decision-controls"><label>Rodada<select id="participant-round"><option value="0">Todas as rodadas</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}">${n}ª rodada</option>`).join('')}</select></label></div><p id="participant-status" role="status">Carregamento sob demanda.</p><div id="participant-kpis" class="decision-metrics"></div><div id="participant-types" class="table-scroll"></div><p class="caption">Pessoa física/jurídica é inferida apenas do formato do documento mascarado. Não revela porte, faturamento, experiência técnica, beneficiário final ou grupo econômico.</p></section><div class="grid"><section class="panel"><h2>Modalidade de participação</h2><div id="participant-modalities"></div><p class="caption">Contagem de linhas do arquivo. O mesmo cadastro pode aparecer em mais de uma modalidade e rodada.</p></section><section class="panel"><h2>Municípios declarados dos participantes</h2><label>Filtrar município ou UF<input id="participant-city" type="search" placeholder="Digite para localizar"></label><div id="participant-locations" class="table-scroll sim-result"></div><p class="caption">Local informado no cadastro do participante, não localização da área. Todas as localidades estão disponíveis na tabela.</p></section></div><section class="panel"><h2>Como interpretar a concentração</h2><p id="participant-concentration"></p><p>Os resultados ligam <b>vencedor, área e valor vencedor</b>. O cadastro geral de interessados não contém a área pretendida nem o valor de cada lance. Não calculamos taxa de vitória individual, competição por área ou propensão de uma pessoa a oferecer determinado valor.</p><p>Identificação analítica por nome normalizado e documento mascarado: variações cadastrais podem separar a mesma pessoa; nomes e máscaras coincidentes podem unir pessoas diferentes. Os grupos são aproximações cadastrais, sem reconstituição de CPF/CNPJ. Nenhuma identidade é enviada nesta visualização.</p><p>Uma próxima modelagem de comportamento exige vínculos de participação por área, lances válidos e não vencedores, data de entrada e regras da rodada. Histórico de vitórias só poderia entrar como informação anterior à rodada avaliada. Esses dados não foram incorporados como preditores nesta versão.</p><a href="https://dadosabertos.anm.gov.br/SOPLE/" target="_blank" rel="noopener">Fonte: InteressadoParticipante e ResultadoRodadaDisponibilidade · ANM</a></section>`);
let participantsData=null,currentParticipant;
const tiles=items=>items.map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('');
async function showParticipants(){try{if(!participantsData){$('participant-status').textContent='Carregando indicadores agregados…';const r=await fetch('participants.json');if(!r.ok)throw Error('Não foi possível carregar os participantes.');participantsData=await r.json()}const rd=+$('participant-round').value;const o=currentParticipant=rd?participantsData.rounds.find(r=>r.round===rd):participantsData.all;$('participant-status').textContent=`Extração: ${String(participantsData.snapshot).slice(0,10)}. ${o.records?num(o.records)+' registros de participação; '+num(o.duplicates)+' duplicatas exatas identificadas (mantidas nas contagens de linhas).':'Sem registros de participantes neste arquivo para a seleção; não significa ausência de participação na rodada.'}`;
$('participant-kpis').innerHTML=tiles([['Cadastros distintos de participantes',o.records?num(o.participants):'Sem registro'],['Cadastros vencedores distintos',o.won?num(o.winners):'Não se aplica'],['Áreas arrematadas',num(o.won)],['Lances vencedores registrados',o.won?shortMoney(o.bids):'Não se aplica']]);$('participant-types').innerHTML='<table><thead><tr><th>Formato cadastral</th><th>Participantes distintos</th><th>Áreas arrematadas</th><th>Lances vencedores</th></tr></thead><tbody>'+o.types.map(t=>`<tr><td>${t.type}</td><td>${o.records?num(t.participants):'Sem registro'}</td><td>${num(t.won)}</td><td>${o.won?money(t.bids):'Não se aplica'}</td></tr>`).join('')+'</tbody></table>';$('participant-modalities').innerHTML=Object.entries(o.modalities).map(([s,n])=>bar(s,n,o.records,'#1351b4')).join('')||'<p>Sem registros nesta seleção.</p>';$('participant-concentration').textContent=o.won?`${num(o.multiple)} cadastros vencedores arremataram mais de uma área na seleção. Os dez maiores totais por cadastro concentram ${pct(o.top10_share)} dos lances vencedores. Não é concentração por grupo econômico nem por todos os concorrentes.`:'Sem resultado de arrematação comercial nesta seleção. A 6ª é social e a 7ª foi cancelada.';renderParticipantLocations()}catch(e){$('participant-status').textContent=e.message}}
function renderParticipantLocations(){if(!currentParticipant)return;const q=fold($('participant-city').value);const rows=currentParticipant.locations.filter(a=>fold(a.join(' ')).includes(q));$('participant-locations').innerHTML='<table><thead><tr><th>UF</th><th>Município declarado</th><th>Registros</th></tr></thead><tbody>'+rows.map(([uf,city,n])=>`<tr><td>${esc(uf||'Sem registro')}</td><td>${esc(city||'Sem registro')}</td><td>${num(n)}</td></tr>`).join('')+'</tbody></table>'}
$('participant-round').onchange=showParticipants;$('participant-city').oninput=renderParticipantLocations;
section('conclusions',`<section class="panel decision-intro"><h2>O que já apoia uma decisão?</h2><p><b>A consulta integrada já permite comparar oferta, resultados e territórios.</b> O modelo preditivo ainda tem utilidade experimental: melhora algumas métricas, mas não demonstrou precisão financeira suficiente para definir lances ou receita.</p><div class="table-scroll"><table class="decision-table"><thead><tr><th>Quem decide</th><th>Pergunta prática</th><th>Como usar agora</th><th>O que falta validar</th></tr></thead><tbody><tr><td>Gestão da ANM</td><td>Onde estão as áreas livres e qual o perfil das ofertas?</td><td>Filtrar rodadas, municípios e substâncias; comparar o funil e consultar os atos e poligonais. Priorizar investigação de grupos de áreas.</td><td>Causas da falta de interesse, retrato exato do edital e efeito de mudanças de regras.</td></tr><tr><td>Equipe de planejamento</td><td>O modelo ajuda a selecionar áreas para análise técnica?</td><td>No simulador, ajustar um limiar de triagem e comparar quantas arrematações históricas ele recupera e quantas deixa de fora.</td><td>Calibração, estabilidade em nova rodada e benefício da triagem frente a regras simples com a mesma capacidade de análise.</td></tr><tr><td>Minerador</td><td>Que áreas e resultados anteriores merecem estudo?</td><td>Explorar processos comparáveis, histórico, substâncias e valores efetivamente registrados. Usar como informação contextual para diligência.</td><td>Custos, reservas, restrições, concorrência e valoração própria. Não existe lance ótimo validado neste painel.</td></tr><tr><td>Planejamento financeiro</td><td>Quanto será recebido?</td><td>Separar lances registrados de pagamentos. Usar as séries como histórico de oferta e compromisso financeiro.</td><td>Modelo da média monetária, calibração, inadimplência, pagamentos e validação de erro agregado. O total previsto de receita ainda não foi produzido.</td></tr></tbody></table></div></section><section class="panel"><h2>Conclusões do experimento</h2><ul><li>Na 8ª rodada, AUC 0,657: alguma capacidade de ordenar áreas, sem equivaler a 65,7% de acerto.</li><li>Erro médio do lance de cerca de R$ 165,6 mil: redução de apenas 1,6% frente à referência simples.</li><li>Faixas experimentais subestimam a incerteza: cobertura de 62,3%, frente a 80% nominal.</li><li>A escolha de modelos ocorreu na 5ª rodada. A 8ª é avaliação retrospectiva já examinada no estudo inicial, não um teste futuro intocado.</li></ul><p>Não se demonstrou que a ferramenta aumenta arrecadação ou reduz custos. Isso exige comparação operacional, critérios de sucesso definidos previamente e avaliação em nova rodada.</p><button class="br-button primary" onclick="view('simulator')">Experimentar a triagem retrospectiva</button></section>`);
section('simulator',`<section class="panel"><h2>Simulador de triagem · avaliação retrospectiva</h2><p>Selecione um conjunto da <b>8ª rodada</b> e defina a probabilidade mínima para encaminhar uma área à análise técnica. As previsões foram calculadas com os modelos selecionados: boosting básico para arrematação e floresta histórica para lance. Nenhum treinamento ocorre no navegador.</p><p class="notice">Experimento em áreas com resultado já conhecido. O limiar é uma escolha de cenário, não uma recomendação. Alterá-lo depois de ver os resultados não valida uma política futura. Não estima probabilidade de você vencer nem calcula lance ótimo.</p><div class="decision-controls"><label>Estado<select id="sim-state"><option value="">Todos</option></select></label><label>Regime<select id="sim-regime"><option value="">Todos</option></select></label><label>Área mínima (ha)<input id="sim-min" type="number" min="0" value="0"></label><label>Probabilidade mínima (%)<input id="sim-threshold" type="number" min="0" max="100" step="1" value="50"></label><button id="sim-reset">Restaurar</button><button id="sim-export">Baixar cenário CSV</button></div><p id="sim-status" role="status"></p><div id="sim-kpis" class="decision-metrics"></div><div id="sim-comparison" aria-live="polite"></div><div id="sim-table" class="table-scroll sim-result"></div><p class="caption">Tabela: até 100 primeiras áreas ordenadas pelo escore; CSV contém toda a seleção. O valor central previsto é condicional à arrematação; não deve ser multiplicado pelo escore e somado como receita esperada. Poligonais atuais, nomes de vencedores e resultados da própria área não entram como preditores.</p></section>`);
let simRevision=null,simSelected=[];
async function initSimulator(){await ensureAreas();if(!data.model){$('sim-status').textContent='Modelos desatualizados: nova avaliação necessária. Simulação indisponível.';$('sim-kpis').innerHTML='';$('sim-comparison').innerHTML='';$('sim-table').innerHTML='';simSelected=[];return}if(simRevision!==window.areasRevision){const rr=data.rows.filter(r=>r.r===8&&r.pred);for(const [id,key] of [['sim-state','u'],['sim-regime','reg']])$(id).innerHTML='<option value="">Todos</option>'+[...new Set(rr.map(r=>r[key]))].sort().map(v=>`<option>${esc(v)}</option>`).join('');simRevision=window.areasRevision}renderSimulator()}
function renderSimulator(){if(!data?.model)return;const threshold=Number($('sim-threshold').value),min=Number($('sim-min').value);if(!Number.isFinite(threshold)||threshold<0||threshold>100||!Number.isFinite(min)||min<0){$('sim-status').textContent='Informe probabilidade entre 0 e 100 e área mínima não negativa.';simSelected=[];$('sim-kpis').innerHTML='';$('sim-comparison').innerHTML='';$('sim-table').innerHTML='';return}const rows=data.rows.filter(r=>r.r===8&&r.pred&&(!$('sim-state').value||r.u===$('sim-state').value)&&(!$('sim-regime').value||r.reg===$('sim-regime').value)&&Math.abs(r.ha)>=min);simSelected=rows.filter(r=>r.pred.p>=threshold/100).sort((a,b)=>b.pred.p-a.pred.p);const won=rows.filter(r=>r.v>0),selectedWon=simSelected.filter(r=>r.v>0),missed=won.length-selectedWon.length;const ratio=(n,d)=>d?pct(n/d):'Não se aplica';$('sim-status').textContent=num(rows.length)+' áreas elegíveis no cenário · probabilidades ainda não calibradas.';$('sim-kpis').innerHTML=tiles([['Áreas encaminhadas',num(simSelected.length)],['Arrematadas entre encaminhadas',ratio(selectedWon.length,simSelected.length)],['Arrematações recuperadas',ratio(selectedWon.length,won.length)],['Arrematações deixadas de fora',num(missed)]]);$('sim-comparison').innerHTML=`<p><b>Comparação histórica:</b> analisar todas as ${num(rows.length)} áreas incluiria ${num(won.length)} arrematações (${ratio(won.length,rows.length)}). Com limiar de ${threshold}%, seriam analisadas ${num(simSelected.length)}, das quais ${num(selectedWon.length)} foram arrematadas e ${num(simSelected.length-selectedWon.length)} não foram.</p><p><b>Lances efetivamente observados nas áreas encaminhadas:</b> ${money(selectedWon.reduce((s,r)=>s+r.v,0))}. Este valor é uma consulta ao resultado histórico, não previsão de receita nem ganho causado pela triagem.</p>`;$('sim-table').innerHTML='<table><thead><tr><th>Processo</th><th>Probabilidade experimental</th><th>Lance central previsto, se arrematada</th><th>Resultado observado</th><th>Lance observado</th><th>Ficha</th></tr></thead><tbody>'+simSelected.slice(0,100).map((r,i)=>`<tr><td>${esc(formatProcess(r.p))}</td><td>${pct(r.pred.p)}</td><td>${money(r.pred.value)}</td><td>${esc(r.s)}</td><td>${r.v?money(r.v):'Sem lance positivo'}</td><td><button data-sim="${i}">Abrir</button></td></tr>`).join('')+'</tbody></table>';$('sim-table').querySelectorAll('[data-sim]').forEach(b=>b.onclick=()=>detail(-1,simSelected[+b.dataset.sim]))}
['sim-state','sim-regime','sim-min','sim-threshold'].forEach(id=>$(id).onchange=renderSimulator);$('sim-reset').onclick=()=>{$('sim-state').value='';$('sim-regime').value='';$('sim-min').value=0;$('sim-threshold').value=50;renderSimulator()};$('sim-export').onclick=()=>{if(!simSelected.length){$('sim-status').textContent='Nenhuma área válida selecionada para exportar.';return}downloadCSV('mineria-cenario-retrospectivo.csv',[['rodada','processo','probabilidade_experimental','lance_central_condicional','situacao_observada','lance_observado','limiar_percentual'],...simSelected.map(r=>[8,formatProcess(r.p),r.pred.p,r.pred.value,r.s,r.v,$('sim-threshold').value])])};
const territory=document.createElement('section');territory.className='panel';territory.innerHTML=`<h2>Municípios das áreas e distribuição dos resultados</h2><p>Use os filtros de rodada e estado acima. A localização é a registrada na base da rodada; os atributos complementares e as poligonais são do cadastro atual.</p><label>Buscar município<input id="area-city-query" type="search" placeholder="Nome ou UF"></label><div id="municipal-profile" class="table-scroll sim-result"></div><p class="caption">Uma área pode se vincular a vários municípios: conta uma associação em cada um. Para evitar duplicação financeira, o lance é rateado igualmente entre os municípios informados. Esse rateio é analítico, não arrecadação municipal nem divisão física da poligonal.</p><details class="decision-disclosure"><summary>O mapa mostra pontos ou poligonais?</summary><p>Na visão geral, as formas são limites dos estados, coloridos pelos totais de lances. Em Explorar áreas, os pontos são posições representativas dos processos, não limites de cada área. Na ficha individual, o desenho usa os anéis da poligonal atual do SIGMINE, com ampliação e deslocamento. Não foi reconstruída a geometria vigente na data de cada edital.</p></details>`;$('profiles').append(territory);
function renderMunicipalities(){if(!window.areasReady)return;const rd=$('profile-round').value,uf=$('profile-state').value,q=fold($('area-city-query').value),groups=new Map();overviewData.rows.filter(r=>(!rd||r.r==rd)&&(!uf||r.u===uf)).forEach(r=>{const cities=[...new Set(String(r.m||'Sem registro').split(' / ').map(s=>s.trim()).filter(Boolean))];cities.forEach(city=>{const key=city+' / '+r.u;if(!groups.has(key))groups.set(key,{n:0,won:0,free:0,bid:0});const g=groups.get(key);g.n++;g.won+=r.s==='Arrematada';g.free+=r.s==='Livre';g.bid+=(r.v||0)/cities.length})});const a=[...groups].filter(([k])=>fold(k).includes(q)).sort((a,b)=>b[1].bid-a[1].bid);$('municipal-profile').innerHTML='<table><thead><tr><th>Município / UF</th><th>Associações de áreas</th><th>Arrematadas</th><th>Livres</th><th>Lances rateados</th></tr></thead><tbody>'+a.map(([k,g])=>`<tr><td>${esc(k)}</td><td>${num(g.n)}</td><td>${num(g.won)}</td><td>${num(g.free)}</td><td>${money(g.bid)}</td></tr>`).join('')+'</tbody></table>'}
['profile-round','profile-state'].forEach(id=>$(id).addEventListener('change',renderMunicipalities));$('area-city-query').oninput=renderMunicipalities;
['sim-min','sim-threshold'].forEach(id=>$(id).addEventListener('input',renderSimulator));

const explanationSource=document.createElement('p');explanationSource.className='caption';explanationSource.innerHTML='Conceitos de oferta, arrematação e áreas livres: <a href="https://www.gov.br/anm/pt-br/acesso-a-informacao/perguntas-frequentes/disponibilidade-de-areas" target="_blank" rel="noopener">perguntas frequentes da ANM</a>. Consulte também o edital da rodada.';$('funnel').after(explanationSource);

const annex=document.createElement('p');annex.innerHTML='<a href="ciencia/USO_E_HIPOTESES.md" download>Baixar guia de hipóteses, perfis e simulador</a>';methodology.append(annex);
